/* Lossless unknown-property retention, typed forms for the supported UIS subset. */
(function(root){'use strict';
const SCHEMA={type:{type:'integer',label:'组件类型',min:0,max:10,default:'0'},anchor:{type:'integer',label:'锚点',min:0,max:8,default:'4'},tex:{type:'string',label:'普通贴图',default:'guangbiaoa.png'},tex2:{type:'string',label:'长条主体',default:'changtiao.png'},tex3:{type:'string',label:'长条尾端',default:'guangbiaoc.png'},tex4:{type:'string',label:'同型双押贴图',default:'guangbiaob.png'},size:{type:'pair',label:'宽,高',default:'52.8,52.8'},pos:{type:'position',label:'位置 X,Y（UIS 正 Y 向上）',default:'50%,50%'},pos2:{type:'position',label:'终点 / 相对位置',default:'0,0'},rotate:{type:'float',label:'旋转角度',default:'0'},opacity:{type:'float',label:'不透明度 0—100',min:0,max:100,default:'100'},zindex:{type:'integer',label:'层级',default:'0'},interval:{type:'float',label:'动画帧间隔 · ms',min:.001,default:'70'},frame:{type:'frame',label:'动画 / 数字帧集',default:'HitFX/0-31'},frame2:{type:'frame',label:'按住帧集',default:'PressFX/0-31'},frame3:{type:'frame',label:'光效帧集',default:'LightFX/0-31'},fsize:{type:'float',label:'字体尺寸',min:.001,default:'31'},motion:{type:'string',label:'动作引用',default:'combo'},toggle:{type:'string',label:'切换规则表达式（原样保留）',default:'1+2'},text:{type:'string',label:'文本',default:''},color:{type:'color',label:'RGBA 颜色（4 个 0—255）',default:'255,255,255,255'},rect:{type:'rect',label:'触摸区域 X,Y,W,H',default:'0,0,100,100'}};
function parse(text){const nodes=[],comments=[];let current=null,web={};for(const raw of text.replace(/^\uFEFF/,'').split(/\r?\n/)){const line=raw.trim();if(!line)continue;if(line.startsWith('#')||line.startsWith('//')){if(line.startsWith('#@dc-studio-preview ')){try{web=JSON.parse(line.slice(20));}catch(e){comments.push(raw);}}else comments.push(raw);continue;}if(line.startsWith('@')){nodes.push({kind:'directive',raw:line});current=null;continue;}if(line.startsWith(':')||!line.includes('=')){current={kind:line.startsWith(':')?'motion':'section',name:line,props:{}};nodes.push(current);continue;}if(!current)throw Error('属性缺少所属组件：'+line);const at=line.indexOf('='),key=line.slice(0,at).trim();current.props[key]=line.slice(at+1).trim();}return{nodes,comments,web};}
function serialize(doc,{includeWeb=true}={}){const rows=[];for(const n of doc.nodes){if(n.kind==='directive')rows.push(n.raw);else{rows.push('',n.name);for(const [k,v]of Object.entries(n.props))rows.push('    '+k+'='+v);}}const comments=doc.comments.slice();if(includeWeb&&Object.keys(doc.web||{}).length)comments.push('#@dc-studio-preview '+JSON.stringify(doc.web));if(comments.length)rows.push('',...comments);return rows.join('\n').trim()+'\n';}
function sections(doc){return Object.fromEntries(doc.nodes.filter(n=>n.kind==='section').map(n=>[n.name,n.props]));}
function spec(key,value){if(SCHEMA[key])return SCHEMA[key];return{type:/^(true|false)$/i.test(value||'')?'boolean':/^-?\d+$/.test(value||'')?'integer':/^-?\d+(?:\.\d+)?$/.test(value||'')?'float':'string',label:'扩展属性 · 原样保留',default:value||'',unknown:true};}
function validateValue(key,value){const s=spec(key,value),v=String(value).trim();if(s.type==='boolean'&&!/^(true|false)$/.test(v))return'需要 true 或 false';if(['integer','float'].includes(s.type)){const n=Number(v);if(!v||!Number.isFinite(n)||s.type==='integer'&&!Number.isInteger(n))return s.type==='integer'?'需要整数':'需要有限小数';if(s.min!=null&&n<s.min||s.max!=null&&n>s.max)return`范围 ${s.min??'−∞'} 至 ${s.max??'∞'}`;}
 const num='[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)';if(s.type==='pair'&&!new RegExp('^\\s*'+num+'\\s*,\\s*'+num+'\\s*$').test(v))return'格式：宽,高（两个数值）';if(key==='size'&&s.type==='pair'&&v.split(',').some(x=>Number(x)<=0))return'宽与高必须为正数';if(s.type==='rect'){const values=v.split(',');if(values.length!==4)return'格式：X,Y,宽,高';const positionError=validateValue('pos',values.slice(0,2).join(','));if(positionError||values.slice(2).some(x=>!x.trim()||!Number.isFinite(Number(x))||Number(x)<=0))return'位置需有效，宽与高需为正数';}if(s.type==='position'){const unit=num+'(?:%|px)?(?:\\s*[+-]\\s*(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:%|px)?)?',pair=unit+'\\s*,\\s*'+unit;if(!new RegExp('^(?:[A-Za-z_][\\w\\-\\[\\]]*\\s+)?'+pair+'$').test(v))return'格式：50%+10,50%-20 或 press-1 0,0';}if(s.type==='frame'&&!/^[^\s/]+\/\d+-\d+$/.test(v))return'格式：HitFX/0-31 或 combo/0-9';if(s.type==='color'){const a=v.split(',').map(Number);if(a.length!==4||a.some(x=>!Number.isInteger(x)||x<0||x>255))return'格式：R,G,B,A（0—255 整数）';}if(s.type==='string'&&/[\r\n]/.test(v))return'字符串不能换行';return null;}
function required(node){if(node.kind!=='section')return[];if(node.name==='note-[1-6]')return['tex','tex2','tex3','tex4','size'];if(/^note-\d$/.test(node.name))return['pos','pos2'];if(node.name==='score-combo')return['frame','fsize'];return[];}
function validate(doc){const errors=[];for(const n of doc.nodes){if(!n.props)continue;for(const key of required(n))if(!n.props[key])errors.push(n.name+'.'+key+' 为网页预览必填');for(const [key,value]of Object.entries(n.props)){if(n.kind==='motion')continue;const error=validateValue(key,value);if(error)errors.push(n.name+'.'+key+'：'+error);}}return errors;}
root.DCMui={SCHEMA,parse,serialize,sections,spec,validateValue,validate,required};
})(typeof window!=='undefined'?window:globalThis);
